insert into profiles(id,full_name,headline,intro,about,languages,location,tagline,photo_url,resume_url,cv_url,published) values (1,'Syed Qutub Nawaz','Engineering Ideas Into Reality.','I''m Syed Qutub Nawaz, a mechanical engineering student focused on thermal systems, HVAC-R and production engineering, with hands-on experience fabricating and testing working prototypes.',array['I study mechanical engineering in Hyderabad. I completed a Diploma in Mechanical Engineering at Government Polytechnic, Hyderabad (January 2022 – April 2025) and am now pursuing a B.E. in Mechanical Engineering at Muffakham Jah College of Engineering & Technology.','My interests are thermal engineering, HVAC-R and production. I like turning thermodynamics and manufacturing theory into things I can build and test: a forced-convection portable cooler for outdoor workers, and a welded, belt-driven mini grinder taken from drawing to working machine.','I use SolidWorks and AutoCAD to plan parts and assemblies before fabricating them, and I am comfortable with welding, metal fabrication and workshop tools.','I am early in my career and open to roles across HVAC-R, production, manufacturing, quality, maintenance or design, and open to relocation. My foundation in thermodynamics, fluid mechanics and manufacturing processes comes from coursework, labs, workshops and industrial visits.']::text[],array['English (Full professional)','Urdu (Native)','Telugu (Native)','Hindi (Native)']::text[],'Hyderabad, Telangana, India','Mechanical Engineering Student | Thermal Systems & HVAC-R | Production & Manufacturing | Hands-on Fabrication','img/img1.jpg','Syed_Qutub_Nawaz_Resume.pdf','Syed_Qutub_Nawaz_CV.pdf',true) on conflict (id) do update set full_name=excluded.full_name,headline=excluded.headline,intro=excluded.intro,about=excluded.about,languages=excluded.languages,location=excluded.location,tagline=excluded.tagline,photo_url=excluded.photo_url,resume_url=excluded.resume_url,cv_url=excluded.cv_url,published=true;
insert into projects(slug,title,category,summary,featured,tags,tools,metrics,sections,cover_url,gallery,sort,published) values ('portable-thermal-comfort-system','Portable Thermal Comfort System','Thermal Engineering · HVAC-R Prototype','A portable cooling solution designed for outdoor workers.',true,array['Forced convection','Prototype']::text[],array['SolidWorks']::text[],'[{"label":"Temperature drop (reported)","value":"17°C"},{"label":"Battery runtime (reported)","value":"3.8 h"},{"label":"Loaded weight (reported)","value":"1.4 kg"},{"label":"Material cost (reported)","value":"< ₹800"}]'::jsonb,'[{"heading":"Overview","body":"A portable cooling solution designed for outdoor workers, built around forced convection cooling."},{"heading":"Engineering design","body":"A 12V DC fan drives airflow through an insulated chamber and ducted airflow path. The system was modelled as an assembly in SolidWorks."},{"heading":"Components and materials","body":"The SolidWorks assembly tree lists: bucket body, lid, DC fan, two PVC pipes, thermocol insulation and two ice packs."},{"heading":"Fabrication","body":"A physical prototype was fabricated."},{"heading":"Results","body":"Reported figures: 17°C temperature drop, 3.8 hours of battery runtime, 1.4 kg loaded weight and under ₹800 in material cost."}]'::jsonb,'img/img2.jpg',array['img/img2.jpg','img/img3.jpg']::text[],2,true) on conflict (slug) do nothing;
insert into projects(slug,title,category,summary,featured,tags,tools,metrics,sections,cover_url,gallery,sort,published) values ('mini-belt-grinder','Mini Belt Grinder','Production & Fabrication · Diploma Final-Year Project','A mechanical engineering diploma final-year project taken from CAD model to a physical, assembled machine.',true,array['Fabrication','Welding','Transmission']::text[],array['SolidWorks']::text[],'[]'::jsonb,'[{"heading":"Overview","body":"The final-year project of my Diploma in Mechanical Engineering."},{"heading":"CAD modelling","body":"Designed and modelled in SolidWorks."},{"heading":"Components","body":"Welded mild-steel frame, DC motor drive, pulley and belt transmission, and flanged bearing supports."},{"heading":"Fabrication and assembly","body":"Physically fabricated and assembled, including belt tracking and alignment."}]'::jsonb,'img/img4.jpg',array['img/img4.jpg','img/img5.jpg','img/img6.jpg','img/img7.jpg','img/img8.jpg']::text[],3,true) on conflict (slug) do nothing;
insert into projects(slug,title,category,summary,featured,tags,tools,metrics,sections,cover_url,gallery,sort,published) values ('automotive-car-chassis-design','Automotive Car Chassis Design','Automotive Engineering · Mechanical Design','An automotive engineering and mechanical design project. The physical prototype is shown below; CAD visualisation and design details to be added.',true,array['Automotive','Modular chassis','Welded steel']::text[],array[]::text[],'[]'::jsonb,'[{"heading":"Physical prototype","body":"A welded steel chassis frame prototype with a bolted central joint, built and photographed from side, top and front views."},{"heading":"Overview","body":"Presented as an automotive engineering and mechanical design project. Dimensions, materials, simulation results and specifications will be added once supplied; none are stated here to avoid inaccuracies."}]'::jsonb,'img/img9.jpg',array['img/img9.jpg','img/img10.jpg','img/img11.jpg','img/img12.jpg']::text[],1,true) on conflict (slug) do nothing;
insert into projects(slug,title,category,summary,featured,tags,tools,metrics,sections,cover_url,gallery,sort,published) values ('portable-hydraulic-bending-machine','Portable Hydraulic Metal Bending Machine','Product Design · Industrial Product Design Mini Project','A portable hydraulic metal bending machine, designed and prototyped as the mini project for the Industrial Product Design course.',true,array['Hydraulics','DFM/DFA','Product design','Fabrication']::text[],array['SolidWorks']::text[],'[]'::jsonb,'[{"heading":"Design process","body":"Applied the product design process: defined requirements and specifications, generated concepts, and screened them to select the final design. Portability, ergonomics and ease of use were considered throughout."},{"heading":"CAD modelling","body":"3D CAD models, assemblies and production drawings in SolidWorks. The assembly tree lists a welded frame (left and right uprights, top crossmember, base front, rear and side rails), a bending crossmember, a hydraulic bottle jack, a threaded extension and a pump handle."},{"heading":"Materials and manufacturing","body":"Selected materials and manufacturing processes, applying Design for Manufacturing and Assembly (DFM/DFA) principles."},{"heading":"Fabrication","body":"Fabricated a working prototype around a 3-ton hydraulic bottle jack."},{"heading":"Testing","body":"Tested by bending aluminium sheet of around 5–8 mm thickness using the 3-ton hydraulic jack."},{"heading":"Documentation","body":"Presented the product with technical documentation."}]'::jsonb,'img/img13.jpg',array['img/img13.jpg','img/img14.jpg','img/img15.jpg','img/img16.jpg','img/img17.jpg']::text[],4,true) on conflict (slug) do nothing;
insert into projects(slug,title,category,summary,featured,tags,tools,metrics,sections,cover_url,gallery,sort,published) values ('mechovate-load-bearing-bridge','Load-Bearing Bridge — MECHOVATE','Hackathon · Team Project','A team entry in a 30-hour engineering hackathon at Anurag University, Hyderabad (October 2025).',false,array['Hackathon','Truss','Team']::text[],array['SolidWorks Weldments']::text[],'[{"label":"Duration","value":"30 h"}]'::jsonb,'[{"heading":"Overview","body":"Participation in MECHOVATE, a 30-hour engineering hackathon at Anurag University, Hyderabad, October 2025."},{"heading":"Engineering design","body":"Structural and truss design applying load distribution principles, modelled with SolidWorks Weldments."},{"heading":"Fabrication","body":"Physical fabrication and welding as part of a team-based engineering challenge."}]'::jsonb,'img/img18.jpg',array['img/img18.jpg','img/img19.jpg','img/img20.jpg']::text[],5,true) on conflict (slug) do nothing;
